def _stop_servers(self) -> None:
    for adapter in [self.server_adapter, self.agent_adapter]:
        if adapter:
            adapter.stop()
            adapter.unsubscribe()

def shutdown(self) -> None:

try:
    self.server_adapter, self.agent_adapter = start_servers()
